using Test
using Serialization

import Pkg
Pkg.activate("$(@__DIR__)/build")
Pkg.develop(path="$(@__DIR__)/build/TestHooks")
using TestHooks

function runtest()
    @testset "Hooks" begin
        #Test wrappers generated by wrapit
        @test f(A()) == 1
	#Test wrappers declared in the hook functions
	@test TestHooks.f(TestHooks.B()) == 2
    end
end

if "-s" in ARGS #Serialize mode
    Test.TESTSET_PRINT_ENABLE[] = false
    serialize(stdout, runtest())
else
    runtest()
end
